package Tv3.Controller;
import Tv3.View.KhoaHocPage;
import MainPage.View.Workspace;import MainPage.Controller.PageTasks;import Model.DanhMucModel;import Service.DanhMucService;import java.util.*;import java.time.LocalDate;import java.math.BigDecimal;import javax.swing.*;
public class KhoaHocController {
 private final KhoaHocPage v;private final int b;private final DanhMucService svc=new DanhMucService();private List<DanhMucModel> data=List.of();private final JCheckBox only;
 public KhoaHocController(KhoaHocPage v,int b){this(v,b,"Cơ sở #"+b);}
 public KhoaHocController(KhoaHocPage v,int b,String name){this.v=v;this.b=b;v.title("KHÓA HỌC — "+name,"Danh mục của cơ sở");v.columns("Mã","Ký hiệu","Tên","Số buổi","Học phí","Phúc lợi","Mô tả","Kích hoạt");only=v.checkFilter("Chỉ đang kích hoạt",this::render);v.action("+ Thêm",()->edit(null));v.action("Sửa",()->{var x=selected();if(x!=null)edit(x);});v.action("Ngừng kích hoạt",()->{var x=selected();if(x!=null&&Workspace.confirm(v,"Ngừng kích hoạt "+x.getTenDanhMuc()+"?"))PageTasks.run(v,()->{x.setTrangThai(false);PageTasks.require(svc.update(b,x),"Không lưu được");return true;},r->load(false));});v.action("Tải lại",()->load(true));load(false);}
 private String field(DanhMucModel x,String k){return PageTasks.field(x==null?null:x.getCauHinh(),k);}
 private boolean active(DanhMucModel x){if(!x.isTrangThai())return false;return true;}
 private void load(boolean force){v.status("Đang tải...");PageTasks.run(v,()->(force?svc.reload(b):svc.selectAll(b)).stream().filter(x->"KHOA_HOC".equals(x.getNhomDanhMuc())).toList(),r->{data=r;render();});}
 private void render(){v.rows(data.stream().filter(x->!only.isSelected()||active(x)).map(x->new Object[]{x.getMaDanhMuc(),x.getMaKyHieu(),x.getTenDanhMuc(),field(x,"TongSoBuoi"),field(x,"HocPhiMacDinh"),field(x,"PhucLoi"),field(x,"MoTa"),x.isTrangThai()}).toArray(Object[][]::new));v.status("Tổng: "+data.size());}
 private DanhMucModel selected(){int r=v.selected();if(r<0){Workspace.message(v,"Chọn dòng trước");return null;}int id=(int)v.value(r,0);return data.stream().filter(x->x.getMaDanhMuc()==id).findFirst().orElse(null);}
 private void edit(DanhMucModel x){try{Workspace.Form form=new Workspace.Form(Workspace.Field.text("Ký hiệu",x==null?"":x.getMaKyHieu()),Workspace.Field.text("Tên",x==null?"":x.getTenDanhMuc()),Workspace.Field.text("Số buổi",field(x,"TongSoBuoi")),Workspace.Field.text("Học phí",field(x,"HocPhiMacDinh")),Workspace.Field.text("Phúc lợi",field(x,"PhucLoi")),Workspace.Field.text("Mô tả",field(x,"MoTa")),Workspace.Field.check("Kích hoạt",x==null||x.isTrangThai()));if(form.show(v,"Khóa học","Lưu","Hủy")!=0)return;int n=Integer.parseInt(form.text(2).trim());BigDecimal p=new BigDecimal(form.text(3).trim());PageTasks.require(n>0&&p.signum()>=0,"Số buổi và học phí không hợp lệ");String config=PageTasks.mergeFields(x==null?null:x.getCauHinh(),Map.of("TongSoBuoi",String.valueOf(n),"HocPhiMacDinh",p.toPlainString(),"PhucLoi",PageTasks.jsonString(form.text(4)),"MoTa",PageTasks.jsonString(form.text(5))));boolean on=form.checked(6);String key=form.text(0).trim(),label=form.text(1).trim();PageTasks.run(v,()->{DanhMucModel m=x==null?new DanhMucModel():x;m.setNhomDanhMuc("KHOA_HOC");m.setMaKyHieu(key);m.setTenDanhMuc(label);m.setCauHinh(config);m.setTrangThai(on);PageTasks.require(x==null?svc.insert(b,m):svc.update(b,m),"Không lưu được danh mục");return true;},r->load(false));}catch(Exception e){Workspace.message(v,"WARNING — "+e.getMessage());}}
}
